import {FISH,FISH_LEDGER_TYPES,FISH_COST_TYPES,FISH_PRICES} from './fish-config.js';
/** Cross-check persisted purchases, services and sale proceeds against the one shared ledger. @param {import('./engine.js').State} state */
export function validateFishEconomy(state){const g=state.fish;if(!g)return;const entries=state.ledger.filter(l=>FISH_LEDGER_TYPES.includes(l.type)),sum=(/** @type {string} */type)=>entries.filter(l=>l.type===type).reduce((n,l)=>n+l.amount,0);if(!g.visited&&entries.length)throw Error('Unvisited Fish ledger');const s=g.stats;
 if(sum('fish.feed_purchase')!==-s.feedBoughtG/FISH.feedBagG*FISH.feedBagCoins||s.feedBoughtG%FISH.feedBagG||sum('fish.water_purchase')!==-s.waterBoughtL/FISH.exchangeL*FISH.exchangeCoins||s.waterBoughtL%FISH.exchangeL||sum('fish.fingerling_purchase')!==-(s.stockedCount-g.recovery.advanceCount)*FISH.fingerlingCoins||s.stockedMassG!==s.stockedCount*FISH.fingerlingG||sum('fish.advance_repayment')!==-g.recovery.repaymentCoins)throw Error('Fish purchase ledger drift');
 const costs=-entries.filter(l=>FISH_COST_TYPES.includes(l.type)).reduce((n,l)=>n+l.amount,0),revenue=entries.filter(l=>!FISH_COST_TYPES.includes(l.type)).reduce((n,l)=>n+l.amount,0);if(s.costCoins!==costs||s.revenueCoins!==revenue||s.soldG!==s.soldAG+s.soldBG+s.soldCG||s.soldAG%FISH.maxMassG||s.soldBG%FISH.maxMassG||s.soldCG%FISH.maxMassG||sum('fish.sale')*1000!==s.soldAG*FISH_PRICES.A+s.soldBG*FISH_PRICES.B+s.soldCG*FISH_PRICES.C||s.soldG!==s.soldCount*FISH.maxMassG||entries.filter(l=>l.type==='fish.sale').length!==s.saleActions)throw Error('Fish sale ledger drift');
 const efficiency=new Set(),filters=new Set(),feeders=new Set(),ponds=new Set([1]);let airTicks=0,filterTicks=0;for(const l of entries){if(l.amount===0||l.tick<g.enteredTick)throw Error('Invalid Fish ledger payment');if(['fish.aerator_upgrade','fish.biofilter_purchase','fish.feeder_purchase','fish.pond_expansion','fish.energy','fish.filter_energy'].includes(l.type)){const match=l.id.match(/\.([12])$/),id=match?Number(match[1]):0;if(!id||!g.ponds.some(p=>p.id===id))throw Error('Invalid Fish service source');if(l.type==='fish.aerator_upgrade'){if(efficiency.has(id)||l.amount!==-FISH.efficiencyCoins)throw Error('Invalid Fish efficiency purchase');efficiency.add(id);}if(l.type==='fish.biofilter_purchase'){if(filters.has(id)||l.amount!==-FISH.filterCoins)throw Error('Invalid Fish filter purchase');filters.add(id);}if(l.type==='fish.feeder_purchase'){if(feeders.has(id)||l.amount!==-FISH.feederCoins)throw Error('Invalid Fish feeder purchase');feeders.add(id);}if(l.type==='fish.pond_expansion'){if(id!==2||ponds.has(id)||l.amount!==-FISH.pondCoins||g.ponds.find(p=>p.id===id)?.createdTick!==l.tick)throw Error('Invalid Fish expansion purchase');ponds.add(id);}if(l.type==='fish.energy'){if(l.amount!==-FISH.airCoins)throw Error('Invalid Fish air payment');airTicks+=efficiency.has(id)?FISH.efficientAirTicks:FISH.airTicks;}if(l.type==='fish.filter_energy'){if(!filters.has(id)||l.amount!==-FISH.airCoins)throw Error('Invalid Fish filter payment');filterTicks+=FISH.airTicks;}}}
 for(const p of g.ponds)if(p.efficient!==efficiency.has(p.id)||p.biofilter!==filters.has(p.id)||p.autoFeeder!==feeders.has(p.id)||!ponds.has(p.id))throw Error('Fish facility proof drift');if(g.ponds.length&&g.ponds.length!==ponds.size||s.paidAirTicks!==airTicks||s.paidFilterTicks!==filterTicks||g.ponds.reduce((n,p)=>n+p.airPaidTicks,0)+s.airUsedTicks!==airTicks||g.ponds.reduce((n,p)=>n+p.filterPaidTicks,0)+s.filterUsedTicks!==filterTicks)throw Error('Fish service accounting drift');
 const bonuses=/** @type {Record<string,number>} */({'fish.delivery':10,'fish.quality':15,'fish.volume':20});if(sum('fish.contract_reward')!==g.contracts.reduce((n,k)=>n+bonuses[k],0))throw Error('Fish contract payout drift');
}
